"""Profile the two product calls on the existing representative sample.

Four segments are timed separately, matching the task statement:
  1. deep normalization   (_normalize_verified_bundle_evolution_checkpoint)
  2. truth recomputation  (_bundle_evolution_checkpoint_is_truthful)
  3. cache-key serialization (sort_keys json.dumps inside the proof cache)
  4. deep copies          (copy.deepcopy)
"""

import copy
import json
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tests"))

import test_bundle_evolution_checkpoint_bundle_diff as fixtures  # noqa: E402

from regulation_policy_compiler import policy  # noqa: E402


class Meter:
    def __init__(self):
        self.normalize = 0.0
        self.truth = 0.0
        self.cache_key = 0.0
        self.deepcopy = 0.0
        self.counts = {"normalize": 0, "truth": 0, "cache_key": 0, "deepcopy": 0}


def install(meter):
    orig_normalize = policy._normalize_verified_bundle_evolution_checkpoint
    orig_truth = policy._bundle_evolution_checkpoint_is_truthful
    orig_deepcopy = copy.deepcopy
    orig_dumps = json.dumps

    def normalize(value, field):
        start = time.perf_counter()
        try:
            return orig_normalize(value, field)
        finally:
            meter.normalize += time.perf_counter() - start
            meter.counts["normalize"] += 1

    def truth(proof):
        start = time.perf_counter()
        try:
            return orig_truth(proof)
        finally:
            meter.truth += time.perf_counter() - start
            meter.counts["truth"] += 1

    def deepcopy(value, *args, **kwargs):
        start = time.perf_counter()
        try:
            return orig_deepcopy(value, *args, **kwargs)
        finally:
            meter.deepcopy += time.perf_counter() - start
            meter.counts["deepcopy"] += 1

    def dumps(value, *args, **kwargs):
        if kwargs.get("sort_keys"):
            start = time.perf_counter()
            try:
                return orig_dumps(value, *args, **kwargs)
            finally:
                meter.cache_key += time.perf_counter() - start
                meter.counts["cache_key"] += 1
        return orig_dumps(value, *args, **kwargs)

    policy._normalize_verified_bundle_evolution_checkpoint = normalize
    policy._bundle_evolution_checkpoint_is_truthful = truth
    copy.deepcopy = deepcopy
    json.dumps = dumps
    return lambda: (
        policy.__dict__.update(
            _normalize_verified_bundle_evolution_checkpoint=orig_normalize,
            _bundle_evolution_checkpoint_is_truthful=orig_truth,
        ),
        globals().__setitem__("copy", copy) if False else None,
    )


def main():
    before = fixtures._bundle_before()
    after = fixtures._bundle_after()

    meter = Meter()

    # cache-key segment: instrument json.dumps/copy.deepcopy in module globals
    orig_normalize = policy._normalize_verified_bundle_evolution_checkpoint
    orig_truth = policy._bundle_evolution_checkpoint_is_truthful
    orig_deepcopy = policy.copy.deepcopy

    def norm(value, field):
        start = time.perf_counter()
        try:
            return orig_normalize(value, field)
        finally:
            meter.normalize += time.perf_counter() - start
            meter.counts["normalize"] += 1

    def truth(proof):
        start = time.perf_counter()
        try:
            return orig_truth(proof)
        finally:
            meter.truth += time.perf_counter() - start
            meter.counts["truth"] += 1

    def deepcopy(value, *args, **kwargs):
        start = time.perf_counter()
        try:
            return orig_deepcopy(value, *args, **kwargs)
        finally:
            meter.deepcopy += time.perf_counter() - start
            meter.counts["deepcopy"] += 1

    policy._normalize_verified_bundle_evolution_checkpoint = norm
    policy._bundle_evolution_checkpoint_is_truthful = truth
    policy.copy.deepcopy = deepcopy
    # json.dumps is looked up as a module global in policy.py
    orig_policy_dumps = policy.json.dumps
    orig_json_dumps = json.dumps

    call_counter = {"key": 0}

    def measured_dumps(value, *args, **kwargs):
        if kwargs.get("sort_keys"):
            start = time.perf_counter()
            try:
                return orig_json_dumps(value, *args, **kwargs)
            finally:
                meter.cache_key += time.perf_counter() - start
                meter.counts["cache_key"] += 1
        return orig_json_dumps(value, *args, **kwargs)

    json.dumps = measured_dumps
    policy.json.dumps = measured_dumps

    t0 = time.perf_counter()
    diff = policy.bundle_evolution_checkpoint_bundle_diff(before, after)
    t_gen = time.perf_counter() - t0
    print(f"GEN total:                {t_gen:8.3f}s")
    print(
        f"  deep normalization:     {meter.normalize:8.3f}s "
        f"(calls {meter.counts['normalize']})"
    )
    print(
        f"  truth recomputation:    {meter.truth:8.3f}s "
        f"(calls {meter.counts['truth']})"
    )
    print(
        f"  cache-key serialization:{meter.cache_key:8.3f}s "
        f"(calls {meter.counts['cache_key']})"
    )
    print(
        f"  deep copies:            {meter.deepcopy:8.3f}s "
        f"(calls {meter.counts['deepcopy']})"
    )
    accounted = meter.normalize + meter.truth + meter.cache_key + meter.deepcopy
    print(f"  (accounted {accounted:.3f}s)")

    # reset meters for verify
    meter2 = Meter()
    expected = {
        "before_root": diff["before_root"],
        "after_root": diff["after_root"],
        "before_ids": [m["id"] for m in diff["before"]["proofs"]],
        "after_ids": [m["id"] for m in diff["after"]["proofs"]],
        "digest": diff["digest"],
    }

    def norm2(value, field):
        start = time.perf_counter()
        try:
            return orig_normalize(value, field)
        finally:
            meter2.normalize += time.perf_counter() - start
            meter2.counts["normalize"] += 1

    def truth2(proof):
        start = time.perf_counter()
        try:
            return orig_truth(proof)
        finally:
            meter2.truth += time.perf_counter() - start
            meter2.counts["truth"] += 1

    def deepcopy2(value, *args, **kwargs):
        start = time.perf_counter()
        try:
            return orig_deepcopy(value, *args, **kwargs)
        finally:
            meter2.deepcopy += time.perf_counter() - start
            meter2.counts["deepcopy"] += 1

    def measured_dumps2(value, *args, **kwargs):
        if kwargs.get("sort_keys"):
            start = time.perf_counter()
            try:
                return orig_json_dumps(value, *args, **kwargs)
            finally:
                meter2.cache_key += time.perf_counter() - start
                meter2.counts["cache_key"] += 1
        return orig_json_dumps(value, *args, **kwargs)

    policy._normalize_verified_bundle_evolution_checkpoint = norm2
    policy._bundle_evolution_checkpoint_is_truthful = truth2
    policy.copy.deepcopy = deepcopy2
    json.dumps = measured_dumps2
    policy.json.dumps = measured_dumps2

    t0 = time.perf_counter()
    ok = policy.verify_bundle_evolution_checkpoint_bundle_diff(diff, expected)
    t_ver = time.perf_counter() - t0
    print(f"VERIFY total:             {t_ver:8.3f}s  result={ok}")
    print(
        f"  deep normalization:     {meter2.normalize:8.3f}s "
        f"(calls {meter2.counts['normalize']})"
    )
    print(
        f"  truth recomputation:    {meter2.truth:8.3f}s "
        f"(calls {meter2.counts['truth']})"
    )
    print(
        f"  cache-key serialization:{meter2.cache_key:8.3f}s "
        f"(calls {meter2.counts['cache_key']})"
    )
    print(
        f"  deep copies:            {meter2.deepcopy:8.3f}s "
        f"(calls {meter2.counts['deepcopy']})"
    )
    accounted = meter2.normalize + meter2.truth + meter2.cache_key + meter2.deepcopy
    print(f"  (accounted {accounted:.3f}s)")


if __name__ == "__main__":
    main()

