"""Measure physical structure sizes and per-op costs of the sample proofs."""
import json
import sys
import time
from pathlib import Path

ROOT = Path("/ddb/cap1/ca/task063")
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tests"))

import test_bundle_evolution_checkpoint_bundle_diff as F  # noqa: E402

p12 = F._window_proof_raw("2021-09-01T00:00:00Z", "2021-10-01T00:00:00Z")
# wrong: proofs keyed on DT times; use correct ones
p12 = F._window_proof_raw(F.DT1, F.DT2)
p23 = F._window_proof_raw(F.DT2, F.DT3)
p33 = F._window_proof_raw(F.DT3, F.DT3)
p13 = F._window_proof_raw(F.DT1, F.DT3)

before = F._bundle_before_raw()
after = F._bundle_after_raw()


def nodes(v):
    if isinstance(v, dict):
        return 1 + sum(nodes(x) for x in v.values())
    if isinstance(v, list):
        return 1 + sum(nodes(x) for x in v)
    return 1


for name, v in [("p12", p12), ("p23", p23), ("p33", p33), ("p13", p13),
                ("before_bundle", before), ("after_bundle", after)]:
    n = nodes(v)
    t0 = time.perf_counter()
    for _ in range(3):
        b = json.dumps(v, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    t_key = (time.perf_counter() - t0) / 3
    t0 = time.perf_counter()
    for _ in range(3):
        b2 = json.dumps(v, ensure_ascii=False, separators=(",", ":"))
    t_canon = (time.perf_counter() - t0) / 3
    print(f"{name:14s} nodes={n:7d} bytes={len(b):8d} key_dumps={t_key*1000:7.1f}ms canon_dumps={t_canon*1000:7.1f}ms")

# count physical occurrences at each layer within one p12 + p33 (the diff sample)
def count_layers(v, c):
    if isinstance(v, dict):
        keys = set(v)
        if keys == {"start", "end", "anchor", "stages", "commitment"}:
            # which kind? stages bundles have root,proofs vs root,reports
            sb = v["stages"][0]["bundle"]
            if set(sb) == {"root", "proofs"}:
                mp = sb["proofs"][0]["proof"]
                if set(mp["stages"][0]["bundle"]) == {"root", "proofs"}:
                    c["L2w"] += 1
                else:
                    c["L0w"] += 1
            else:
                c["Lm1w"] += 1
            for s in v["stages"]:
                count_layers(s["bundle"], c)
                if s["diff"] is not None:
                    count_layers(s["diff"], c)
        elif keys == {"root", "proofs"}:
            if "proof" in v["proofs"][0]:
                c["Lxb_proofs"] += 1
                for m in v["proofs"]:
                    count_layers(m["proof"], c)
        elif keys == {"root", "reports"}:
            c["matrix_bundle"] += 1
            for m in v["reports"]:
                c["matrix_cred"] += 1
        elif keys == {"before_root", "after_root", "before", "after", "changes", "digest"}:
            c["diff"] += 1
            count_layers(v["before"], c)
            count_layers(v["after"], c)
            for ch in v["changes"]:
                count_layers(ch["before"], c)
                count_layers(ch["after"], c)
        else:
            for x in v.values():
                count_layers(x, c)
    elif isinstance(v, list):
        for x in v:
            count_layers(x, c)

c = {"L2w": 0, "L0w": 0, "Lm1w": 0, "Lxb_proofs": 0, "matrix_bundle": 0, "matrix_cred": 0, "diff": 0}
for p in (p12, p23, p33, p13):
    count_layers(p, c)
print("occurrences across 4 unique L2w proofs (physical):", c)

