# ---------------------------------------------------------------------------
# Value-identity proof engine (shared by the bundle-evolution bundle diff
# generator and verifier).
#
# A single top-level diff call physically contains the same deep credentials,
# bundles, proofs, and diffs thousands of times but only a handful of distinct
# values (2-5 at each nesting level).  The engine parses, canonicalizes, and
# recomputes each *distinct* value exactly once:
#
#   * identity is a value key, never an object identity (equal declared values
#     share one result; differing values never merge);
#   * composite keys are assembled from child value keys and scalar fields, so
#     a whole multi-megabyte deep proof is never serialized to build a key --
#     only leaf credentials are fully serialized (they are the bounded base
#     case and their bytes are the digest payload anyway);
#   * canonical compact JSON is composed bottom-up from the cached bytes of
#     children, so member, stage, and diff digests reuse intermediate values;
#   * canonical containers are shared read-only *inside* the engine and deep
#     copied only when emitted into a result, keeping inputs, the two bundles,
#     and change sides isolated.
# ---------------------------------------------------------------------------


def _engine_key(tag: str, body: str) -> str:
    return hashlib.sha256((tag + "\x00" + body).encode("utf-8")).hexdigest()


def _engine_jstr(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


class _EngineNode:
    __slots__ = (
        "key",
        "canonical",
        "json",
        "sem",
        "stage_sem",
        "truth",
        "root",
        "members",
        "complete",
    )

    def __init__(self) -> None:
        self.key: str = ""
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.stage_sem: Any = None
        self.truth: bool = False
        self.root: str = ""
        self.members: list[Any] = []
        self.complete: bool = True

    def emit(self) -> Any:
        """Fresh independent deep copy of the canonical value."""
        return copy.deepcopy(self.canonical)


class _ProofEngine:
    """Parse/canonicalize/recompute the nested proof stack once per value."""

    def __init__(self) -> None:
        self.cred: dict[str, _EngineNode] = {}
        self.mbundle: dict[str, _EngineNode] = {}
        self.mdiff: dict[str, _EngineNode] = {}
        self.p0: dict[str, _EngineNode] = {}
        self.b0: dict[str, _EngineNode] = {}
        self.d0: dict[str, _EngineNode] = {}
        self.p1: dict[str, _EngineNode] = {}
        self.b1: dict[str, _EngineNode] = {}
        self.d1: dict[str, _EngineNode] = {}
        self.p2: dict[str, _EngineNode] = {}
        self.b2: dict[str, _EngineNode] = {}

    # ------------------------------------------------------------- leaf ----
    def credential(self, value: Any, field: str) -> _EngineNode:
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        canonical = copy.deepcopy(content)
        canonical["digest"] = declared
        cjson = _engine_jstr(canonical)
        key = _engine_key("cred", cjson)
        node = self.cred.get(key)
        if node is not None:
            return node
        node = _EngineNode()
        node.key = key
        node.canonical = canonical
        node.json = cjson
        node.sem = _matrix_credential_semantics(content)
        node.truth = bool(
            chain_ok and content["policy"]["root"] == chain_root and declared == recomputed
        )
        self.cred[key] = node
        return node

    # ------------------------------------------------------- matrix bundle --
    def matrix_bundle(self, value: Any, field: str) -> _EngineNode:
        if not isinstance(value, dict) or set(value) != set(_MATRIX_BUNDLE_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, reports"
            )
        bundle_root = _check_hex64(value["root"], f"{field}.root")
        raw_reports = value["reports"]
        if not isinstance(raw_reports, list) or not raw_reports:
            raise ValueError(f"{field}.reports must be a non-empty list")
        members: list[tuple[str, _EngineNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw_reports):
            mf = f"{field}.reports[{index}]"
            if not isinstance(member, dict) or set(member) != set(
                _MATRIX_BUNDLE_MEMBER_KEYS
            ):
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    "id, report, previous, digest"
