            if item_id in seen:
                raise ValueError(f"{field}.reports contains a duplicate id: {item_id!r}")
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.reports must be ordered by id in ascending "
                    "Unicode code point order"
                )
            cred = self.credential(member["report"], f"{mf}.report")
            prev = _check_hex64(member["previous"], f"{mf}.previous")
            dig = _check_hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, cred, prev, dig))
            seen.add(item_id)
            previous_id = item_id
        body = bundle_root + "[" + ",".join(
            f"({i},{c.key},{p},{d})" for i, c, p, d in members
        ) + "]"
        key = _engine_key("mbundle", body)
        node = self.mbundle.get(key)
        if node is not None:
            return node

        # member digest chain (uses cached credential bytes)
        truth = True
        running = _MATRIX_BUNDLE_GENESIS
        member_json_parts: list[str] = []
        for item_id, cred, prev, dig in members:
            payload = (
                '{"id":' + _engine_jstr(item_id) + ',"report":' + cred.json + "}"
            )
            member_json_parts.append(
                '{"id":' + _engine_jstr(item_id)
                + ',"report":' + cred.json
                + ',"previous":' + _engine_jstr(prev)
                + ',"digest":' + _engine_jstr(dig) + "}"
            )
            recomputed_dig = hashlib.sha256(
                running.encode("ascii") + payload.encode("utf-8")
            ).hexdigest()
            if not cred.truth or prev != running or dig != recomputed_dig:
                truth = False
            running = recomputed_dig
        if bundle_root != running:
            truth = False
        bjson = (
            '{"root":' + _engine_jstr(bundle_root)
            + ',"reports":[' + ",".join(member_json_parts) + "]}"
        )
        canonical = {
            "root": bundle_root,
            "reports": [
                {
                    "id": item_id,
                    "report": cred.emit(),
                    "previous": prev,
                    "digest": dig,
                }
                for item_id, cred, prev, dig in members
            ],
        }
        node = _EngineNode()
        node.key = key
        node.canonical = canonical
        node.json = bjson
        node.root = bundle_root
        node.members = members
        node.sem = [(item_id, cred.sem) for item_id, cred, _p, _d in members]
        node.truth = truth
        self.mbundle[key] = node
        return node

    # --------------------------------------------------------- matrix diff --
    def _diff_changes_cred(
        self,
        value: Any,
        before_members: list[tuple[str, _EngineNode, str, str]],
        after_members: list[tuple[str, _EngineNode, str, str]],
        field: str,
    ) -> list[tuple[str, str, _EngineNode | None, _EngineNode | None]]:
        if not isinstance(value, list):
            raise ValueError(f"{field} must be a list of change dicts")
        before_by_id = {m[0]: m for m in before_members}
        after_by_id = {m[0]: m for m in after_members}
        entries: list[tuple[str, str, _EngineNode | None, _EngineNode | None]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, change in enumerate(value):
            cf = f"{field}[{index}]"
            if not isinstance(change, dict) or set(change) != _MATRIX_BUNDLE_DIFF_CHANGE_KEYS:
                raise ValueError(
                    f"{cf} must be a dict with exactly the keys id, kind, before, after"
                )
            member_id = _check_non_empty_str(change["id"], f"{cf}.id")
            if member_id in seen:
                raise ValueError(f"{field} contains a duplicate change id: {member_id!r}")
            if previous_id is not None and member_id <= previous_id:
                raise ValueError(
                    f"{field} must be ordered by id in ascending Unicode code "
                    "point order"
                )
            kind = change["kind"]
            if kind not in _MATRIX_BUNDLE_DIFF_KINDS:
                raise ValueError(
                    f"{cf}.kind must be 'added', 'removed', or 'changed'"
                )
            before_node = (
                None if change["before"] is None
                else self.credential(change["before"], f"{cf}.before")
            )
            after_node = (
                None if change["after"] is None
                else self.credential(change["after"], f"{cf}.after")
            )
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if kind == "added":
                if before_node is not None or after_node is None:
                    raise ValueError(
                        f"{cf} is 'added' but before/after do not match the contract"
                    )
                if bm is not None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not added between the two bundles"
                    )
                if after_node.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle's credential "
                        f"for id {member_id!r}"
                    )
            elif kind == "removed":
                if before_node is None or after_node is not None:
                    raise ValueError(
                        f"{cf} is 'removed' but before/after do not match the contract"
                    )
                if bm is None or am is not None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not removed between the two bundles"
                    )
                if before_node.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle's credential "
                        f"for id {member_id!r}"
                    )
            else:
                if before_node is None or after_node is None:
                    raise ValueError(
                        f"{cf} is 'changed' but before/after do not match the contract"
                    )
                if bm is None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} must exist in both bundles to be 'changed'"
                    )
                if before_node.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle's credential "
                        f"for id {member_id!r}"
                    )
                if after_node.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle's credential "
                        f"for id {member_id!r}"
                    )
            entries.append((member_id, kind, before_node, after_node))
            seen.add(member_id)
            previous_id = member_id
        expected = set(before_by_id) ^ set(after_by_id)
        for member_id in sorted(set(before_by_id) & set(after_by_id)):
            if before_by_id[member_id][1].sem != after_by_id[member_id][1].sem:
                expected.add(member_id)
        # Matrix diffs treat an incomplete change set as a structural error.
        if seen != expected:
            raise ValueError(
                "changes must list exactly the added, removed, and changed "
                "members, with unchanged members omitted"
            )
        return entries

    def matrix_diff(self, value: Any, field: str) -> _EngineNode:
        if not isinstance(value, dict) or set(value) != set(_MATRIX_BUNDLE_DIFF_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "before_root, after_root, before, after, changes, digest"
            )
        before_root = _check_hex64(value["before_root"], f"{field}.before_root")
        after_root = _check_hex64(value["after_root"], f"{field}.after_root")
        digest = _check_hex64(value["digest"], f"{field}.digest")
        before = self.matrix_bundle(value["before"], f"{field}.before")
        after = self.matrix_bundle(value["after"], f"{field}.after")
        if before.root != before_root:
            raise ValueError(f"{field}.before_root must equal {field}.before.root")
        if after.root != after_root:
            raise ValueError(f"{field}.after_root must equal {field}.after.root")
        entries = self._diff_changes_cred(
            value["changes"], before.members, after.members, f"{field}.changes"
        )
        body = (
            before_root + after_root + digest
            + before.key + after.key
            + "[" + ",".join(
                f"({i},{k},{bn.key if bn else ''},{an.key if an else ''})"
                for i, k, bn, an in entries
            ) + "]"
        )
        key = _engine_key("mdiff", body)
        node = self.mdiff.get(key)
        if node is not None:
            return node

        change_parts: list[str] = []
        truth = before.truth and after.truth
        for member_id, kind, bn, an in entries:
            bp = "null" if bn is None else bn.json
            ap = "null" if an is None else an.json
            change_parts.append(
                '{"id":' + _engine_jstr(member_id)
                + ',"kind":' + _engine_jstr(kind)
                + ',"before":' + bp + ',"after":' + ap + "}"
            )
            if (bn is not None and not bn.truth) or (an is not None and not an.truth):
                truth = False
        five = (
            '{"before_root":' + _engine_jstr(before_root)
            + ',"after_root":' + _engine_jstr(after_root)
            + ',"before":' + before.json
            + ',"after":' + after.json
            + ',"changes":[' + ",".join(change_parts) + "]}"
        )
        recomputed = hashlib.sha256(five.encode("utf-8")).hexdigest()
        if digest != recomputed:
            truth = False
        cjson = five[:-1] + ',"digest":' + _engine_jstr(digest) + "}"
        node = _EngineNode()
        node.key = key
        node.json = cjson
        node.root = before_root
        node.truth = truth
        node.stage_sem = {
            "before": before.sem,
            "after": after.sem,
            "changes": [
                {
                    "id": member_id,
                    "kind": kind,
                    "before": None if bn is None else bn.sem,
                    "after": None if an is None else an.sem,
                }
                for member_id, kind, bn, an in entries
            ],
        }
        self.mdiff[key] = node
        return node

    # ------------------------------------------------ generic proof stage ---
    def _proof(
        self,
        tag: str,
        registry: dict[str, _EngineNode],
        value: Any,
        field: str,
        genesis: str,
        bundle_kind: str,
        bundle_parse: Any,
        diff_kind: str,
        diff_parse: Any,
        proof_sem_bundle_sem: Any,
    ) -> _EngineNode:
        if not isinstance(value, dict) or set(value) != {
            "start", "end", "anchor", "stages", "commitment"
        }:
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "start, end, anchor, stages, commitment"
            )
        start = _check_time(value["start"], f"{field}.start")
        end = _check_time(value["end"], f"{field}.end")
        if start > end:
            raise ValueError(f"{field}.start must not be after {field}.end")
        anchor = _check_hex64(value["anchor"], f"{field}.anchor")
        commitment = _check_hex64(value["commitment"], f"{field}.commitment")
        raw_stages = value["stages"]
        if not isinstance(raw_stages, list) or not raw_stages:
            raise ValueError(f"{field}.stages must be a non-empty list")

        stage_rows: list[tuple[str, _EngineNode, _EngineNode | None, str, str]] = []
        previous_at: str | None = None
        for index, stage in enumerate(raw_stages):
            sf = f"{field}.stages[{index}]"
            if not isinstance(stage, dict) or set(stage) != {
                "at", "bundle", "diff", "previous", "digest"
            }:
                raise ValueError(
                    f"{sf} must be a dict with exactly the keys "
                    "at, bundle, diff, previous, digest"
                )
            at = _check_time(stage["at"], f"{sf}.at")
            if previous_at is not None and at <= previous_at:
                raise ValueError(
                    f"{sf}.at must be strictly greater than the preceding stage at"
                )
            previous_digest = _check_hex64(stage["previous"], f"{sf}.previous")
            dig = _check_hex64(stage["digest"], f"{sf}.digest")
            bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
            diff: _EngineNode | None
            if index == 0 and previous_digest == genesis:
                if stage["diff"] is not None:
                    raise ValueError(f"{sf}.diff must be null at the genesis stage")
                diff = None
            else:
                diff = diff_parse(stage["diff"], f"{sf}.diff")
                if diff.root != bundle.root and not (
                    index == 0 and diff_kind == "mdiff"
                ):
                    pass
                if index == 0:
                    if diff.root_after != bundle.root:  # type: ignore[attr-defined]
                        raise ValueError(
                            f"{sf}.diff.after_root must equal this stage bundle root"
                        )
                    if diff.stage_sem["after"] != bundle.sem:
                        raise ValueError(
                            f"{sf}.diff.after must reproduce this stage bundle"
                        )
                else:
                    preceding = stage_rows[-1]
                    preceding_bundle = preceding[1]
                    if diff.root_before != preceding_bundle.root:  # type: ignore[attr-defined]
                        raise ValueError(
                            f"{sf}.diff.before_root must equal the preceding "
                            "stage bundle root"
                        )
                    if diff.root_after != bundle.root:  # type: ignore[attr-defined]
                        raise ValueError(
                            f"{sf}.diff.after_root must equal this stage bundle root"
                        )
                    if diff.stage_sem["before"] != preceding_bundle.sem:
                        raise ValueError(
                            f"{sf}.diff.before must reproduce the preceding stage bundle"
                        )
                    if diff.stage_sem["after"] != bundle.sem:
                        raise ValueError(
                            f"{sf}.diff.after must reproduce this stage bundle"
                        )
            stage_rows.append((at, bundle, diff, previous_digest, dig))
            previous_at = at

        body = (
            start + end + anchor + commitment
            + "[" + ",".join(
                f"({at},{b.key},"
                + ("" if d is None else d.key)
                + f",{p},{h})"
                for at, b, d, p, h in stage_rows
            ) + "]"
        )
        key = _engine_key(tag, body)
        node = registry.get(key)
        if node is not None:
            return node

        truth = True
        running = anchor
        stage_parts: list[str] = []
        sem_stages: list[dict[str, Any]] = []
        for index, (at, bundle, diff, previous_digest, dig) in enumerate(stage_rows):
            if not bundle.truth:
                truth = False
            if diff is not None and not diff.truth:
                truth = False
            if previous_digest != running:
                truth = False
            stage_payload = (
                '{"at":' + _engine_jstr(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + "}"
            )
            recomputed = hashlib.sha256(
                running.encode("ascii") + stage_payload.encode("utf-8")
            ).hexdigest()
            if dig != recomputed:
                truth = False
            running = recomputed
            stage_parts.append(
                '{"at":' + _engine_jstr(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + ',"previous":' + _engine_jstr(previous_digest)
                + ',"digest":' + _engine_jstr(dig) + "}"
            )
            sem_stages.append(
                {
                    "at": at,
                    "bundle": copy.deepcopy(bundle.sem),
                    "diff": None if diff is None else copy.deepcopy(diff.stage_sem),
                }
            )
        if commitment != running:
            truth = False
        if not (start == stage_rows[0][0] and end == stage_rows[-1][0]):
            truth = False
        pjson = (
            '{"start":' + _engine_jstr(start)
            + ',"end":' + _engine_jstr(end)
            + ',"anchor":' + _engine_jstr(anchor)
            + ',"stages":[' + ",".join(stage_parts)
            + '],"commitment":' + _engine_jstr(commitment) + "}"
        )
        node = _EngineNode()
        node.key = key
        node.json = pjson
        node.truth = truth
        node.sem = {"start": start, "end": end, "stages": sem_stages}
        registry[key] = node
        return node
