"""Value-identity proof engine (appended into policy.py).

Shared by bundle_evolution_checkpoint_bundle_diff (generate) and
verify_bundle_evolution_checkpoint_bundle_diff (verify). It parses,
canonicalizes, and recomputes every *distinct* nested value exactly once:

* identity is a value key (equal declared values share one result; different
  values never merge), built bottom-up from child value keys and scalars, so
  a whole multi-megabyte deep proof is never serialized to make a key;
* canonical compact JSON is composed bottom-up from cached child bytes, so
  member, stage, and diff digests reuse intermediate values;
* canonical containers live in the engine and are deep copied per output slot,
  so inputs, the two bundles, and the change sides stay isolated.
"""


def _vk(tag: str, body: str) -> str:
    return hashlib.sha256((tag + "\x00" + body).encode("utf-8")).hexdigest()


def _vjs(value: Any) -> str:
    # Scalar JSON (ids, kinds, hex digests); non-ASCII stays unescaped.
    return json.dumps(value, ensure_ascii=False)


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "dsem", "truth", "complete",
        "root", "members",
    )

    def __init__(self) -> None:
        self.key: str = ""
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None       # value projection (credential/proof/bundle)
        self.dsem: Any = None      # diff projection
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.members: list[Any] = []


def _member_digest_bytes(previous: str, member_key: str, item_id: str, child_json: str) -> str:
    payload = (
        '{"id":' + _vjs(item_id) + ',"' + member_key + '":' + child_json + "}"
    )
    return hashlib.sha256(
        previous.encode("ascii") + payload.encode("utf-8")
    ).hexdigest(), payload


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[str, _VNode] = {}
        self.mdiff: dict[str, _VNode] = {}
        self.p0: dict[str, _VNode] = {}
        self.b0: dict[str, _VNode] = {}
        self.d0: dict[str, _VNode] = {}
        self.p1: dict[str, _VNode] = {}
        self.b1: dict[str, _VNode] = {}
        self.d1: dict[str, _VNode] = {}
        self.p2: dict[str, _VNode] = {}
        self.b2: dict[str, _VNode] = {}
        self.d2: dict[str, _VNode] = {}

    # ---------------------------------------------------------------- leaf
    def credential(self, value: Any, field: str) -> _VNode:
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        canonical = copy.deepcopy(content)
        canonical["digest"] = declared
        cjson = json.dumps(canonical, ensure_ascii=False, separators=(",", ":"))
        node = self.cred.get(_vk("cred", cjson))
        if node is not None:
            return node
        node = _VNode()
        node.canonical = canonical
        node.json = cjson
        node.key = _vk("cred", cjson)
        node.sem = _matrix_credential_semantics(content)
        node.truth = bool(
            chain_ok
            and content["policy"]["root"] == chain_root
            and declared == recomputed
        )
        self.cred[node.key] = node
        return node

    # -------------------------------------------------------- matrix bundle
    def matrix_bundle(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict) or set(value) != set(_MATRIX_BUNDLE_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, reports"
            )
        root = _check_hex64(value["root"], f"{field}.root")
        members = self._bundle_members(
            value, field, "reports", "report",
            lambda v, f: self.credential(v, f),
        )
        body = root + "[" + ",".join(
            f"({i},{n.key},{p},{d})" for i, n, p, d in members
        ) + "]"
        node = self.mbundle.get(_vk("mbundle", body))
        if node is not None:
            return node

        truth, running, parts = True, _MATRIX_BUNDLE_GENESIS, []
        for item_id, child, prev, dig in members:
            recomputed, _payload = _member_digest_bytes(
                running, "report", item_id, child.json
            )
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"report":' + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = _vk("mbundle", body)
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.json = (
            '{"root":' + _vjs(root) + ',"reports":[' + ",".join(parts) + "]}"
        )
        node.canonical = {
            "root": root,
            "reports": [
                {
                    "id": i,
                    "report": copy.deepcopy(n.canonical),
                    "previous": p,
                    "digest": d,
                }
                for i, n, p, d in members
            ],
        }
        self.mbundle[node.key] = node
        return node

    def _bundle_members(
        self, value, field, plural, singular, parse_child
    ) -> list[tuple[str, _VNode, str, str]]:
        raw = value[plural]
        if not isinstance(raw, list) or not raw:
            raise ValueError(f"{field}.{plural} must be a non-empty list")
        members: list[tuple[str, _VNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw):
            mf = f"{field}.{plural}[{index}]"
            if not isinstance(member, dict) or set(member) != {
                "id", singular, "previous", "digest"
            }:
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    f"id, {singular}, previous, digest"
                )
            item_id = _check_non_empty_str(member["id"], f"{mf}.id")
            if item_id in seen:
                raise ValueError(
                    f"{field}.{plural} contains a duplicate id: {item_id!r}"
                )
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.{plural} must be ordered by id in ascending "
                    "Unicode code point order"
                )
            child = parse_child(member[singular], f"{mf}.{singular}")
            prev = _check_hex64(member["previous"], f"{mf}.previous")
            dig = _check_hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, child, prev, dig))
            seen.add(item_id)
            previous_id = item_id
        return members

    # ---------------------------------------------------------- matrix diff
    def matrix_diff(self, value: Any, field: str) -> _VNode:
        node, _b, _a, entries = self._parse_diff(
            "mdiff", self.mdiff, value, field,
            bundle_parse=lambda v, f: self.matrix_bundle(v, f),
            side_parse=lambda v, f: self.credential(v, f),
            strict=True,
        )
        return node

    # --------------------------------------------------------- proof bundles
    def proof_bundle(self, level: int, value: Any, field: str) -> _VNode:
        reg = {0: self.b0, 1: self.b1, 2: self.b2}[level]
        proof_parse = {0: self.evolution_proof, 1: self.chain_proof,
                       2: self.bundle_evolution_proof}[level]
        if not isinstance(value, dict) or set(value) != set(_CHECKPOINT_BUNDLE_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, proofs"
            )
        root = _check_hex64(value["root"], f"{field}.root")
        members = self._bundle_members(
            value, field, "proofs", "proof", proof_parse
        )
        body = root + "[" + ",".join(
            f"({i},{n.key},{p},{d})" for i, n, p, d in members
        ) + "]"
        tag = {0: "b0", 1: "b1", 2: "b2"}[level]
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node

        truth, running, parts = True, _CHECKPOINT_BUNDLE_GENESIS, []
        for item_id, child, prev, dig in members:
            recomputed, _payload = _member_digest_bytes(
                running, "proof", item_id, child.json
            )
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"proof":' + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = _vk(tag, body)
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.json = (
            '{"root":' + _vjs(root) + ',"proofs":[' + ",".join(parts) + "]}"
        )
        node.canonical = {
            "root": root,
            "proofs": [
                {
                    "id": i,
                    "proof": copy.deepcopy(n.canonical),
                    "previous": p,
                    "digest": d,
                }
                for i, n, p, d in members
            ],
        }
        reg[node.key] = node
        return node

    # ----------------------------------------------------------- proof diffs
    def proof_diff(self, level: int, value: Any, field: str) -> _VNode:
        reg = {0: self.d0, 1: self.d1, 2: self.d2}[level]
        bundle_parse = {
            0: lambda v, f: self.proof_bundle(0, v, f),
            1: lambda v, f: self.proof_bundle(1, v, f),
            2: lambda v, f: self.proof_bundle(2, v, f),
        }[level]
        side_parse = {
            0: lambda v, f: self.evolution_proof(v, f),
            1: lambda v, f: self.chain_proof(v, f),
            2: lambda v, f: self.bundle_evolution_proof(v, f),
        }[level]
        tag = {0: "d0", 1: "d1", 2: "d2"}[level]
        node, _b, _a, _entries = self._parse_diff(
            tag, reg, value, field,
            bundle_parse=bundle_parse, side_parse=side_parse, strict=False,
        )
        return node

    def _parse_diff(
        self, tag, reg, value, field, bundle_parse, side_parse, strict
    ):
        if not isinstance(value, dict) or set(value) != set(
            _CHECKPOINT_BUNDLE_DIFF_REPORT_KEYS
        ):
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "before_root, after_root, before, after, changes, digest"
            )
        before_root = _check_hex64(value["before_root"], f"{field}.before_root")
        after_root = _check_hex64(value["after_root"], f"{field}.after_root")
        digest = _check_hex64(value["digest"], f"{field}.digest")
        before = bundle_parse(value["before"], f"{field}.before")
        after = bundle_parse(value["after"], f"{field}.after")
        if before.root != before_root:
            raise ValueError(f"{field}.before_root must equal {field}.before.root")
        if after.root != after_root:
            raise ValueError(f"{field}.after_root must equal {field}.after.root")
        entries, complete = self._diff_changes(
            value["changes"], before.members, after.members,
            f"{field}.changes", side_parse, strict,
        )
        body = (
            before_root + after_root + digest + before.key + after.key
            + "[" + ",".join(
                f"({i},{k},{bn.key if bn is not None else ''},"
                f"{an.key if an is not None else ''})"
                for i, k, bn, an in entries
            ) + "]"
        )
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node, before, after, entries

        truth = before.truth and after.truth
        change_parts: list[str] = []
        for _id, kind, bn, an in entries:
            if (bn is not None and not bn.truth) or (
                an is not None and not an.truth
            ):
                truth = False
            change_parts.append(
                '{"id":' + _vjs(_id)
                + ',"kind":' + _vjs(kind)
                + ',"before":' + ("null" if bn is None else bn.json)
                + ',"after":' + ("null" if an is None else an.json)
                + "}"
            )
        five = (
            '{"before_root":' + _vjs(before_root)
            + ',"after_root":' + _vjs(after_root)
            + ',"before":' + before.json
            + ',"after":' + after.json
            + ',"changes":[' + ",".join(change_parts) + "]}"
        )
        recomputed = hashlib.sha256(five.encode("utf-8")).hexdigest()
        if digest != recomputed:
            truth = False
        node = _VNode()
        node.key = _vk(tag, body)
        node.root = before_root
        node.truth = truth
        node.complete = complete
        node.json = five[:-1] + ',"digest":' + _vjs(digest) + "}"
        node.dsem = {
            "before": before.sem,
            "after": after.sem,
            "changes": [
                {
                    "id": _id,
                    "kind": kind,
                    "before": None if bn is None else bn.sem,
                    "after": None if an is None else an.sem,
                }
                for _id, kind, bn, an in entries
            ],
        }
        node.members = entries
        reg[node.key] = node
        return node, before, after, entries

    def _diff_changes(
        self, value, before_members, after_members, field, side_parse, strict
    ):
        if not isinstance(value, list):
            raise ValueError(f"{field} must be a list of change dicts")
        before_by_id = {m[0]: m for m in before_members}
        after_by_id = {m[0]: m for m in after_members}
        entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, change in enumerate(value):
            cf = f"{field}[{index}]"
            if not isinstance(change, dict) or set(change) != (
                _CHECKPOINT_BUNDLE_DIFF_CHANGE_KEYS
            ):
                raise ValueError(
                    f"{cf} must be a dict with exactly the keys "
                    "id, kind, before, after"
                )
            member_id = _check_non_empty_str(change["id"], f"{cf}.id")
            if member_id in seen:
                raise ValueError(f"{field} contains a duplicate change id: {member_id!r}")
            if previous_id is not None and member_id <= previous_id:
                raise ValueError(
                    f"{field} must be ordered by id in ascending Unicode code "
                    "point order"
                )
            kind = change["kind"]
            if kind not in _CHECKPOINT_BUNDLE_DIFF_KINDS:
                raise ValueError(
                    f"{cf}.kind must be 'added', 'removed', or 'changed'"
                )
            bn = None if change["before"] is None else side_parse(
                change["before"], f"{cf}.before"
            )
            an = None if change["after"] is None else side_parse(
                change["after"], f"{cf}.after"
            )
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if kind == "added":
                if bn is not None or an is None:
                    raise ValueError(
                        f"{cf} is 'added' but before/after do not match the contract"
                    )
                if bm is not None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not added between the two bundles"
                    )
                if an.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            elif kind == "removed":
                if bn is None or an is not None:
                    raise ValueError(
                        f"{cf} is 'removed' but before/after do not match the contract"
                    )
                if bm is None or am is not None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not removed between the two bundles"
                    )
                if bn.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
            else:
                if bn is None or an is None:
                    raise ValueError(
                        f"{cf} is 'changed' but before/after do not match the contract"
                    )
                if bm is None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} must exist in both bundles "
                        "to be 'changed'"
                    )
                if bn.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
                if an.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            entries.append((member_id, kind, bn, an))
            seen.add(member_id)
            previous_id = member_id

        expected = set(before_by_id) ^ set(after_by_id)
        for member_id in sorted(set(before_by_id) & set(after_by_id)):
            if before_by_id[member_id][1].sem != after_by_id[member_id][1].sem:
                expected.add(member_id)
        if strict:
            if seen != expected:
                raise ValueError(
                    "changes must list exactly the added, removed, and changed "
                    "members, with unchanged members omitted"
                )
        return entries, seen == expected

    # ------------------------------------------------------------- proofs
    def _proof(self, tag, reg, value, field, genesis, bundle_parse, diff_parse):
        if not isinstance(value, dict) or set(value) != {
            "start", "end", "anchor", "stages", "commitment"
        }:
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "start, end, anchor, stages, commitment"
            )
        start = _check_time(value["start"], f"{field}.start")
        end = _check_time(value["end"], f"{field}.end")
        if start > end:
            raise ValueError(f"{field}.start must not be after {field}.end")
        anchor = _check_hex64(value["anchor"], f"{field}.anchor")
        commitment = _check_hex64(value["commitment"], f"{field}.commitment")
        raw_stages = value["stages"]
        if not isinstance(raw_stages, list) or not raw_stages:
            raise ValueError(f"{field}.stages must be a non-empty list")

        rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
        previous_at: str | None = None
        for index, stage in enumerate(raw_stages):
            sf = f"{field}.stages[{index}]"
            if not isinstance(stage, dict) or set(stage) != {
                "at", "bundle", "diff", "previous", "digest"
            }:
                raise ValueError(
                    f"{sf} must be a dict with exactly the keys "
                    "at, bundle, diff, previous, digest"
                )
            at = _check_time(stage["at"], f"{sf}.at")
            if previous_at is not None and at <= previous_at:
                raise ValueError(
                    f"{sf}.at must be strictly greater than the preceding stage at"
                )
            prev = _check_hex64(stage["previous"], f"{sf}.previous")
            dig = _check_hex64(stage["digest"], f"{sf}.digest")
            bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
            diff: _VNode | None
            if index == 0 and prev == genesis:
                if stage["diff"] is not None:
                    raise ValueError(f"{sf}.diff must be null at the genesis stage")
                diff = None
            elif index == 0:
                diff = diff_parse(stage["diff"], f"{sf}.diff")
                if diff.root != bundle.root:
                    raise ValueError(
                        f"{sf}.diff.after_root must equal this stage bundle root"
                    )
                if diff.dsem["after"] != bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.after must reproduce this stage bundle"
                    )
            else:
                diff = diff_parse(stage["diff"], f"{sf}.diff")
                preceding_bundle = rows[-1][1]
                if diff.dsem["before"] != preceding_bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.before must reproduce the preceding stage bundle"
                    )
                if diff.dsem["after"] != bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.after must reproduce this stage bundle"
                    )
            rows.append((at, bundle, diff, prev, dig))
            previous_at = at

        body = (
            start + end + anchor + commitment
            + "[" + ",".join(
                f"({at},{b.key}," + ("" if d is None else d.key) + f",{p},{h})"
                for at, b, d, p, h in rows
            ) + "]"
        )
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node

        truth = True
        running = anchor
        stage_parts: list[str] = []
        sem_stages: list[dict[str, Any]] = []
        for index, (at, bundle, diff, prev, dig) in enumerate(rows):
            if not bundle.truth:
                truth = False
            if diff is not None:
                if index == 0:
                    if not diff.truth or not diff.complete:
                        truth = False
                else:
                    generated = self._generate_proof_diff(
                        tag[1], rows[index - 1][1], bundle
                    )
                    if diff.key != generated.key:
                        truth = False
            stage_payload = (
                '{"at":' + _vjs(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + "}"
            )
            recomputed = hashlib.sha256(
                running.encode("ascii") + stage_payload.encode("utf-8")
            ).hexdigest()
            if prev != running or dig != recomputed:
                truth = False
            running = recomputed
            stage_parts.append(
                '{"at":' + _vjs(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            sem_stages.append(
                {
                    "at": at,
                    "bundle": bundle.sem,
                    "diff": None if diff is None else diff.dsem,
                }
            )
        if commitment != running:
            truth = False
        if not (start == rows[0][0] and end == rows[-1][0]):
            truth = False

        canonical_stages = []
        for at, bundle, diff, prev, dig in rows:
            canonical_stages.append(
                {
                    "at": at,
                    "bundle": copy.deepcopy(bundle.canonical),
                    "diff": None if diff is None else copy.deepcopy(
                        self._diff_canonical(tag[1], diff)
                    ),
                    "previous": prev,
                    "digest": dig,
                }
            )
        node = _VNode()
        node.key = _vk(tag, body)
        node.truth = truth
        node.json = (
            '{"start":' + _vjs(start)
            + ',"end":' + _vjs(end)
            + ',"anchor":' + _vjs(anchor)
            + ',"stages":[' + ",".join(stage_parts)
            + '],"commitment":' + _vjs(commitment) + "}"
        )
        node.sem = {"start": start, "end": end, "stages": sem_stages}
        node.canonical = {
            "start": start,
            "end": end,
            "anchor": anchor,
            "stages": canonical_stages,
            "commitment": commitment,
        }
        reg[node.key] = node
        return node

    def evolution_proof(self, value, field):
        return self._proof(
            "p0", self.p0, value, field, _MATRIX_BUNDLE_EVOLUTION_GENESIS,
            lambda v, f: self.matrix_bundle(v, f),
            lambda v, f: self.matrix_diff(v, f),
        )

    def chain_proof(self, value, field):
        return self._proof(
            "p1", self.p1, value, field, _CHECKPOINT_CHAIN_GENESIS,
            lambda v, f: self.proof_bundle(0, v, f),
            lambda v, f: self.proof_diff(0, v, f),
        )

    def bundle_evolution_proof(self, value, field):
        return self._proof(
            "p2", self.p2, value, field, _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
            lambda v, f: self.proof_bundle(1, v, f),
            lambda v, f: self.proof_diff(1, v, f),
        )

    def _diff_canonical(self, level: str, node: _VNode):
        # Reconstruct canonical dict from the cached diff json is avoided;
        # build from member child canonicals via the registry entries.
        reg = {"0": self.d0, "1": self.d1, "2": self.d2, "m": self.mdiff}[level]
        # node.members holds parsed entries; need roots/bundles from json parse.
        # Simpler: store canonical on diff node at parse time.
        return node._canonical  # type: ignore[attr-defined]

    def _generate_proof_diff(self, level: str, before: _VNode, after: _VNode) -> _VNode:
        """Canonical d-level diff between two canonical bundle nodes."""
        tag = {"0": "d0", "1": "d1", "2": "d2"}[level]
        reg = {"0": self.d0, "1": self.d1, "2": self.d2}[level]
        before_by_id = {m[0]: m for m in before.members}
        after_by_id = {m[0]: m for m in after.members}
        entries = []
        for member_id in sorted(set(before_by_id) | set(after_by_id)):
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if (
                bm is not None and am is not None
                and bm[1].key == am[1].key
            ):
                continue
            kind = "added" if bm is None else "removed" if am is None else "changed"
            entries.append((member_id, kind, None if bm is None else bm[1],
                            None if am is None else am[1]))
        change_parts = []
        for _id, kind, bn, an in entries:
            change_parts.append(
                '{"id":' + _vjs(_id)
                + ',"kind":' + _vjs(kind)
                + ',"before":' + ("null" if bn is None else bn.json)
                + ',"after":' + ("null" if an is None else an.json)
                + "}"
            )
        five = (
            '{"before_root":' + _vjs(before.root)
            + ',"after_root":' + _vjs(after.root)
            + ',"before":' + before.json
            + ',"after":' + after.json
            + ',"changes":[' + ",".join(change_parts) + "]}"
        )
        digest = hashlib.sha256(five.encode("utf-8")).hexdigest()
        body = (
            before.root + after.root + digest + before.key + after.key
            + "[" + ",".join(
                f"({i},{k},{bn.key if bn is not None else ''},"
                f"{an.key if an is not None else ''})"
                for i, k, bn, an in entries
            ) + "]"
        )
        node = _VNode()
        node.key = _vk(tag, body)
        node.truth = True
        node.complete = True
        node.root = before.root
        node.json = five[:-1] + ',"digest":' + _vjs(digest) + "}"
        reg[node.key] = node
        return node

toolUseResult.content:
"""Value-identity proof engine (appended into policy.py).

Shared by bundle_evolution_checkpoint_bundle_diff (generate) and
verify_bundle_evolution_checkpoint_bundle_diff (verify). It parses,
canonicalizes, and recomputes every *distinct* nested value exactly once:

* identity is a value key (equal declared values share one result; different
  values never merge), built bottom-up from child value keys and scalars, so
  a whole multi-megabyte deep proof is never serialized to make a key;
* canonical compact JSON is composed bottom-up from cached child bytes, so
  member, stage, and diff digests reuse intermediate values;
* canonical containers live in the engine and are deep copied per output slot,
  so inputs, the two bundles, and the change sides stay isolated.
"""


def _vk(tag: str, body: str) -> str:
    return hashlib.sha256((tag + "\x00" + body).encode("utf-8")).hexdigest()


def _vjs(value: Any) -> str:
    # Scalar JSON (ids, kinds, hex digests); non-ASCII stays unescaped.
    return json.dumps(value, ensure_ascii=False)


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "dsem", "truth", "complete",
        "root", "members",
    )

    def __init__(self) -> None:
        self.key: str = ""
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None       # value projection (credential/proof/bundle)
        self.dsem: Any = None      # diff projection
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.members: list[Any] = []


def _member_digest_bytes(previous: str, member_key: str, item_id: str, child_json: str) -> str:
    payload = (
        '{"id":' + _vjs(item_id) + ',"' + member_key + '":' + child_json + "}"
    )
    return hashlib.sha256(
        previous.encode("ascii") + payload.encode("utf-8")
    ).hexdigest(), payload


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[str, _VNode] = {}
        self.mdiff: dict[str, _VNode] = {}
        self.p0: dict[str, _VNode] = {}
        self.b0: dict[str, _VNode] = {}
        self.d0: dict[str, _VNode] = {}
        self.p1: dict[str, _VNode] = {}
        self.b1: dict[str, _VNode] = {}
        self.d1: dict[str, _VNode] = {}
        self.p2: dict[str, _VNode] = {}
        self.b2: dict[str, _VNode] = {}
        self.d2: dict[str, _VNode] = {}

    # ---------------------------------------------------------------- leaf
    def credential(self, value: Any, field: str) -> _VNode:
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        canonical = copy.deepcopy(content)
        canonical["digest"] = declared
        cjson = json.dumps(canonical, ensure_ascii=False, separators=(",", ":"))
        node = self.cred.get(_vk("cred", cjson))
        if node is not None:
            return node
        node = _VNode()
        node.canonical = canonical
        node.json = cjson
        node.key = _vk("cred", cjson)
        node.sem = _matrix_credential_semantics(content)
        node.truth = bool(
            chain_ok
            and content["policy"]["root"] == chain_root
            and declared == recomputed
        )
        self.cred[node.key] = node
        return node

    # -------------------------------------------------------- matrix bundle
    def matrix_bundle(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict) or set(value) != set(_MATRIX_BUNDLE_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, reports"
            )
        root = _check_hex64(value["root"], f"{field}.root")
        members = self._bundle_members(
            value, field, "reports", "report",
            lambda v, f: self.credential(v, f),
        )
        body = root + "[" + ",".join(
            f"({i},{n.key},{p},{d})" for i, n, p, d in members
        ) + "]"
        node = self.mbundle.get(_vk("mbundle", body))
        if node is not None:
            return node

        truth, running, parts = True, _MATRIX_BUNDLE_GENESIS, []
        for item_id, child, prev, dig in members:
            recomputed, _payload = _member_digest_bytes(
                running, "report", item_id, child.json
            )
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"report":' + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = _vk("mbundle", body)
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.json = (
            '{"root":' + _vjs(root) + ',"reports":[' + ",".join(parts) + "]}"
        )
        node.canonical = {
            "root": root,
            "reports": [
                {
                    "id": i,
                    "report": copy.deepcopy(n.canonical),
                    "previous": p,
                    "digest": d,
                }
                for i, n, p, d in members
            ],
        }
        self.mbundle[node.key] = node
        return node

    def _bundle_members(
        self, value, field, plural, singular, parse_child
    ) -> list[tuple[str, _VNode, str, str]]:
        raw = value[plural]
        if not isinstance(raw, list) or not raw:
            raise ValueError(f"{field}.{plural} must be a non-empty list")
        members: list[tuple[str, _VNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw):
            mf = f"{field}.{plural}[{index}]"
            if not isinstance(member, dict) or set(member) != {
                "id", singular, "previous", "digest"
            }:
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    f"id, {singular}, previous, digest"
                )
            item_id = _check_non_empty_str(member["id"], f"{mf}.id")
            if item_id in seen:
                raise ValueError(
                    f"{field}.{plural} contains a duplicate id: {item_id!r}"
                )
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.{plural} must be ordered by id in ascending "
                    "Unicode code point order"
                )
            child = parse_child(member[singular], f"{mf}.{singular}")
            prev = _check_hex64(member["previous"], f"{mf}.previous")
            dig = _check_hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, child, prev, dig))
            seen.add(item_id)
            previous_id = item_id
        return members

    # ---------------------------------------------------------- matrix diff
    def matrix_diff(self, value: Any, field: str) -> _VNode:
        node, _b, _a, entries = self._parse_diff(
            "mdiff", self.mdiff, value, field,
            bundle_parse=lambda v, f: self.matrix_bundle(v, f),
            side_parse=lambda v, f: self.credential(v, f),
            strict=True,
        )
        return node

    # --------------------------------------------------------- proof bundles
    def proof_bundle(self, level: int, value: Any, field: str) -> _VNode:
        reg = {0: self.b0, 1: self.b1, 2: self.b2}[level]
        proof_parse = {0: self.evolution_proof, 1: self.chain_proof,
                       2: self.bundle_evolution_proof}[level]
        if not isinstance(value, dict) or set(value) != set(_CHECKPOINT_BUNDLE_REPORT_KEYS):
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, proofs"
            )
        root = _check_hex64(value["root"], f"{field}.root")
        members = self._bundle_members(
            value, field, "proofs", "proof", proof_parse
        )
        body = root + "[" + ",".join(
            f"({i},{n.key},{p},{d})" for i, n, p, d in members
        ) + "]"
        tag = {0: "b0", 1: "b1", 2: "b2"}[level]
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node

        truth, running, parts = True, _CHECKPOINT_BUNDLE_GENESIS, []
        for item_id, child, prev, dig in members:
            recomputed, _payload = _member_digest_bytes(
                running, "proof", item_id, child.json
            )
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"proof":' + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = _vk(tag, body)
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.json = (
            '{"root":' + _vjs(root) + ',"proofs":[' + ",".join(parts) + "]}"
        )
        node.canonical = {
            "root": root,
            "proofs": [
                {
                    "id": i,
                    "proof": copy.deepcopy(n.canonical),
                    "previous": p,
                    "digest": d,
                }
                for i, n, p, d in members
            ],
        }
        reg[node.key] = node
        return node

    # ----------------------------------------------------------- proof diffs
    def proof_diff(self, level: int, value: Any, field: str) -> _VNode:
        reg = {0: self.d0, 1: self.d1, 2: self.d2}[level]
        bundle_parse = {
            0: lambda v, f: self.proof_bundle(0, v, f),
            1: lambda v, f: self.proof_bundle(1, v, f),
            2: lambda v, f: self.proof_bundle(2, v, f),
        }[level]
        side_parse = {
            0: lambda v, f: self.evolution_proof(v, f),
            1: lambda v, f: self.chain_proof(v, f),
            2: lambda v, f: self.bundle_evolution_proof(v, f),
        }[level]
        tag = {0: "d0", 1: "d1", 2: "d2"}[level]
        node, _b, _a, _entries = self._parse_diff(
            tag, reg, value, field,
            bundle_parse=bundle_parse, side_parse=side_parse, strict=False,
        )
        return node

    def _parse_diff(
        self, tag, reg, value, field, bundle_parse, side_parse, strict
    ):
        if not isinstance(value, dict) or set(value) != set(
            _CHECKPOINT_BUNDLE_DIFF_REPORT_KEYS
        ):
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "before_root, after_root, before, after, changes, digest"
            )
        before_root = _check_hex64(value["before_root"], f"{field}.before_root")
        after_root = _check_hex64(value["after_root"], f"{field}.after_root")
        digest = _check_hex64(value["digest"], f"{field}.digest")
        before = bundle_parse(value["before"], f"{field}.before")
        after = bundle_parse(value["after"], f"{field}.after")
        if before.root != before_root:
            raise ValueError(f"{field}.before_root must equal {field}.before.root")
        if after.root != after_root:
            raise ValueError(f"{field}.after_root must equal {field}.after.root")
        entries, complete = self._diff_changes(
            value["changes"], before.members, after.members,
            f"{field}.changes", side_parse, strict,
        )
        body = (
            before_root + after_root + digest + before.key + after.key
            + "[" + ",".join(
                f"({i},{k},{bn.key if bn is not None else ''},"
                f"{an.key if an is not None else ''})"
                for i, k, bn, an in entries
            ) + "]"
        )
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node, before, after, entries

        truth = before.truth and after.truth
        change_parts: list[str] = []
        for _id, kind, bn, an in entries:
            if (bn is not None and not bn.truth) or (
                an is not None and not an.truth
            ):
                truth = False
            change_parts.append(
                '{"id":' + _vjs(_id)
                + ',"kind":' + _vjs(kind)
                + ',"before":' + ("null" if bn is None else bn.json)
                + ',"after":' + ("null" if an is None else an.json)
                + "}"
            )
        five = (
            '{"before_root":' + _vjs(before_root)
            + ',"after_root":' + _vjs(after_root)
            + ',"before":' + before.json
            + ',"after":' + after.json
            + ',"changes":[' + ",".join(change_parts) + "]}"
        )
        recomputed = hashlib.sha256(five.encode("utf-8")).hexdigest()
        if digest != recomputed:
            truth = False
        node = _VNode()
        node.key = _vk(tag, body)
        node.root = before_root
        node.truth = truth
        node.complete = complete
        node.json = five[:-1] + ',"digest":' + _vjs(digest) + "}"
        node.dsem = {
            "before": before.sem,
            "after": after.sem,
            "changes": [
                {
                    "id": _id,
                    "kind": kind,
                    "before": None if bn is None else bn.sem,
                    "after": None if an is None else an.sem,
                }
                for _id, kind, bn, an in entries
            ],
        }
        node.members = entries
        reg[node.key] = node
        return node, before, after, entries

    def _diff_changes(
        self, value, before_members, after_members, field, side_parse, strict
    ):
        if not isinstance(value, list):
            raise ValueError(f"{field} must be a list of change dicts")
        before_by_id = {m[0]: m for m in before_members}
        after_by_id = {m[0]: m for m in after_members}
        entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, change in enumerate(value):
            cf = f"{field}[{index}]"
            if not isinstance(change, dict) or set(change) != (
                _CHECKPOINT_BUNDLE_DIFF_CHANGE_KEYS
            ):
                raise ValueError(
                    f"{cf} must be a dict with exactly the keys "
                    "id, kind, before, after"
                )
            member_id = _check_non_empty_str(change["id"], f"{cf}.id")
            if member_id in seen:
                raise ValueError(f"{field} contains a duplicate change id: {member_id!r}")
            if previous_id is not None and member_id <= previous_id:
                raise ValueError(
                    f"{field} must be ordered by id in ascending Unicode code "
                    "point order"
                )
            kind = change["kind"]
            if kind not in _CHECKPOINT_BUNDLE_DIFF_KINDS:
                raise ValueError(
                    f"{cf}.kind must be 'added', 'removed', or 'changed'"
                )
            bn = None if change["before"] is None else side_parse(
                change["before"], f"{cf}.before"
            )
            an = None if change["after"] is None else side_parse(
                change["after"], f"{cf}.after"
            )
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if kind == "added":
                if bn is not None or an is None:
                    raise ValueError(
                        f"{cf} is 'added' but before/after do not match the contract"
                    )
                if bm is not None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not added between the two bundles"
                    )
                if an.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            elif kind == "removed":
                if bn is None or an is not None:
                    raise ValueError(
                        f"{cf} is 'removed' but before/after do not match the contract"
                    )
                if bm is None or am is not None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not removed between the two bundles"
                    )
                if bn.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
            else:
                if bn is None or an is None:
                    raise ValueError(
                        f"{cf} is 'changed' but before/after do not match the contract"
                    )
                if bm is None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} must exist in both bundles "
                        "to be 'changed'"
                    )
                if bn.sem != bm[1].sem:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
                if an.sem != am[1].sem:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            entries.append((member_id, kind, bn, an))
            seen.add(member_id)
            previous_id = member_id

        expected = set(before_by_id) ^ set(after_by_id)
        for member_id in sorted(set(before_by_id) & set(after_by_id)):
            if before_by_id[member_id][1].sem != after_by_id[member_id][1].sem:
                expected.add(member_id)
        if strict:
            if seen != expected:
                raise ValueError(
                    "changes must list exactly the added, removed, and changed "
                    "members, with unchanged members omitted"
                )
        return entries, seen == expected

    # ------------------------------------------------------------- proofs
    def _proof(self, tag, reg, value, field, genesis, bundle_parse, diff_parse):
        if not isinstance(value, dict) or set(value) != {
            "start", "end", "anchor", "stages", "commitment"
        }:
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "start, end, anchor, stages, commitment"
            )
        start = _check_time(value["start"], f"{field}.start")
        end = _check_time(value["end"], f"{field}.end")
        if start > end:
            raise ValueError(f"{field}.start must not be after {field}.end")
        anchor = _check_hex64(value["anchor"], f"{field}.anchor")
        commitment = _check_hex64(value["commitment"], f"{field}.commitment")
        raw_stages = value["stages"]
        if not isinstance(raw_stages, list) or not raw_stages:
            raise ValueError(f"{field}.stages must be a non-empty list")

        rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
        previous_at: str | None = None
        for index, stage in enumerate(raw_stages):
            sf = f"{field}.stages[{index}]"
            if not isinstance(stage, dict) or set(stage) != {
                "at", "bundle", "diff", "previous", "digest"
            }:
                raise ValueError(
                    f"{sf} must be a dict with exactly the keys "
                    "at, bundle, diff, previous, digest"
                )
            at = _check_time(stage["at"], f"{sf}.at")
            if previous_at is not None and at <= previous_at:
                raise ValueError(
                    f"{sf}.at must be strictly greater than the preceding stage at"
                )
            prev = _check_hex64(stage["previous"], f"{sf}.previous")
            dig = _check_hex64(stage["digest"], f"{sf}.digest")
            bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
            diff: _VNode | None
            if index == 0 and prev == genesis:
                if stage["diff"] is not None:
                    raise ValueError(f"{sf}.diff must be null at the genesis stage")
                diff = None
            elif index == 0:
                diff = diff_parse(stage["diff"], f"{sf}.diff")
                if diff.root != bundle.root:
                    raise ValueError(
                        f"{sf}.diff.after_root must equal this stage bundle root"
                    )
                if diff.dsem["after"] != bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.after must reproduce this stage bundle"
                    )
            else:
                diff = diff_parse(stage["diff"], f"{sf}.diff")
                preceding_bundle = rows[-1][1]
                if diff.dsem["before"] != preceding_bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.before must reproduce the preceding stage bundle"
                    )
                if diff.dsem["after"] != bundle.sem:
                    raise ValueError(
                        f"{sf}.diff.after must reproduce this stage bundle"
                    )
            rows.append((at, bundle, diff, prev, dig))
            previous_at = at

        body = (
            start + end + anchor + commitment
            + "[" + ",".join(
                f"({at},{b.key}," + ("" if d is None else d.key) + f",{p},{h})"
                for at, b, d, p, h in rows
            ) + "]"
        )
        node = reg.get(_vk(tag, body))
        if node is not None:
            return node

        truth = True
        running = anchor
        stage_parts: list[str] = []
        sem_stages: list[dict[str, Any]] = []
        for index, (at, bundle, diff, prev, dig) in enumerate(rows):
            if not bundle.truth:
                truth = False
            if diff is not None:
                if index == 0:
                    if not diff.truth or not diff.complete:
                        truth = False
                else:
                    generated = self._generate_proof_diff(
                        tag[1], rows[index - 1][1], bundle
                    )
                    if diff.key != generated.key:
                        truth = False
            stage_payload = (
                '{"at":' + _vjs(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + "}"
            )
            recomputed = hashlib.sha256(
                running.encode("ascii") + stage_payload.encode("utf-8")
            ).hexdigest()
            if prev != running or dig != recomputed:
                truth = False
            running = recomputed
            stage_parts.append(
                '{"at":' + _vjs(at)
                + ',"bundle":' + bundle.json
                + ',"diff":' + ("null" if diff is None else diff.json)
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            sem_stages.append(
                {
                    "at": at,
                    "bundle": bundle.sem,
                    "diff": None if diff is None else diff.dsem,
                }
            )
        if commitment != running:
            truth = False
        if not (start == rows[0][0] and end == rows[-1][0]):
            truth = False

        canonical_stages = []
        for at, bundle, diff, prev, dig in rows:
            canonical_stages.append(
                {
                    "at": at,
                    "bundle": copy.deepcopy(bundle.canonical),
                    "diff": None if diff is None else copy.deepcopy(
                        self._diff_canonical(tag[1], diff)
                    ),
                    "previous": prev,
                    "digest": dig,
                }
            )
        node = _VNode()
        node.key = _vk(tag, body)
        node.truth = truth
        node.json = (
            '{"start":' + _vjs(start)
            + ',"end":' + _vjs(end)
            + ',"anchor":' + _vjs(anchor)
            + ',"stages":[' + ",".join(stage_parts)
            + '],"commitment":' + _vjs(commitment) + "}"
        )
        node.sem = {"start": start, "end": end, "stages": sem_stages}
        node.canonical = {
            "start": start,
            "end": end,
            "anchor": anchor,
            "stages": canonical_stages,
            "commitment": commitment,
        }
        reg[node.key] = node
        return node

    def evolution_proof(self, value, field):
        return self._proof(
            "p0", self.p0, value, field, _MATRIX_BUNDLE_EVOLUTION_GENESIS,
            lambda v, f: self.matrix_bundle(v, f),
            lambda v, f: self.matrix_diff(v, f),
        )

    def chain_proof(self, value, field):
        return self._proof(
            "p1", self.p1, value, field, _CHECKPOINT_CHAIN_GENESIS,
            lambda v, f: self.proof_bundle(0, v, f),
            lambda v, f: self.proof_diff(0, v, f),
        )

    def bundle_evolution_proof(self, value, field):
        return self._proof(
            "p2", self.p2, value, field, _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
            lambda v, f: self.proof_bundle(1, v, f),
            lambda v, f: self.proof_diff(1, v, f),
        )

    def _diff_canonical(self, level: str, node: _VNode):
        # Reconstruct canonical dict from the cached diff json is avoided;
        # build from member child canonicals via the registry entries.
        reg = {"0": self.d0, "1": self.d1, "2": self.d2, "m": self.mdiff}[level]
        # node.members holds parsed entries; need roots/bundles from json parse.
        # Simpler: store canonical on diff node at parse time.
        return node._canonical  # type: ignore[attr-defined]

    def _generate_proof_diff(self, level: str, before: _VNode, after: _VNode) -> _VNode:
        """Canonical d-level diff between two canonical bundle nodes."""
        tag = {"0": "d0", "1": "d1", "2": "d2"}[level]
        reg = {"0": self.d0, "1": self.d1, "2": self.d2}[level]
        before_by_id = {m[0]: m for m in before.members}
        after_by_id = {m[0]: m for m in after.members}
        entries = []
        for member_id in sorted(set(before_by_id) | set(after_by_id)):
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if (
                bm is not None and am is not None
                and bm[1].key == am[1].key
            ):
                continue
            kind = "added" if bm is None else "removed" if am is None else "changed"
            entries.append((member_id, kind, None if bm is None else bm[1],
                            None if am is None else am[1]))
        change_parts = []
        for _id, kind, bn, an in entries:
            change_parts.append(
                '{"id":' + _vjs(_id)
                + ',"kind":' + _vjs(kind)
                + ',"before":' + ("null" if bn is None else bn.json)
                + ',"after":' + ("null" if an is None else an.json)
                + "}"
            )
        five = (
            '{"before_root":' + _vjs(before.root)
            + ',"after_root":' + _vjs(after.root)
            + ',"before":' + before.json
            + ',"after":' + after.json
            + ',"changes":[' + ",".join(change_parts) + "]}"
        )
        digest = hashlib.sha256(five.encode("utf-8")).hexdigest()
        body = (
            before.root + after.root + digest + before.key + after.key
            + "[" + ",".join(
                f"({i},{k},{bn.key if bn is not None else ''},"
                f"{an.key if an is not None else ''})"
                for i, k, bn, an in entries
            ) + "]"
        )
        node = _VNode()
        node.key = _vk(tag, body)
        node.truth = True
        node.complete = True
        node.root = before.root
        node.json = five[:-1] + ',"digest":' + _vjs(digest) + "}"
        reg[node.key] = node
        return node

